materials.8008:
天气查询：对照一次协议往返

选择目录请求、目录返回、天气调用或天气返回，对照方向、主要内容与原始消息。目录请求对应编号101；实际查询对应102。编号使应用能把返回配回请求。天气返回为72°F、局部多云，与前面工具调用部分的样例一致。

【请求工具目录】
{
  "jsonrpc": "2.0",
  "id": 101,
  "method": "tools/list",
  "params": {
    "_meta": {
      "io.modelcontextprotocol/protocolVersion": "2026-07-28",
      "io.modelcontextprotocol/clientInfo": {
        "name": "classroom-mcp-client",
        "version": "1.0.0"
      },
      "io.modelcontextprotocol/clientCapabilities": {}
    }
  }
}

【返回工具目录】
{
  "jsonrpc": "2.0",
  "id": 101,
  "result": {
    "resultType": "complete",
    "tools": [
      {
        "name": "get_weather",
        "description": "Get current weather information for a location",
        "inputSchema": {
          "type": "object",
          "properties": {
            "location": {
              "type": "string",
              "description": "City name or zip code"
            }
          },
          "required": [
            "location"
          ]
        }
      }
    ],
    "ttlMs": 300000,
    "cacheScope": "public",
    "_meta": {
      "io.modelcontextprotocol/serverInfo": {
        "name": "classroom-weather-fixture",
        "version": "1.0.0"
      }
    }
  }
}

【调用天气工具】
{
  "jsonrpc": "2.0",
  "id": 102,
  "method": "tools/call",
  "params": {
    "name": "get_weather",
    "arguments": {
      "location": "New York"
    },
    "_meta": {
      "io.modelcontextprotocol/protocolVersion": "2026-07-28",
      "io.modelcontextprotocol/clientInfo": {
        "name": "classroom-mcp-client",
        "version": "1.0.0"
      },
      "io.modelcontextprotocol/clientCapabilities": {}
    }
  }
}

【返回天气内容】
{
  "jsonrpc": "2.0",
  "id": 102,
  "result": {
    "resultType": "complete",
    "content": [
      {
        "type": "text",
        "text": "Current weather in New York:\n Temperature: 72°F\n Conditions: Partly cloudy"
      }
    ],
    "isError": false,
    "_meta": {
      "io.modelcontextprotocol/serverInfo": {
        "name": "classroom-weather-fixture",
        "version": "1.0.0"
      }
    }
  }
}

工具调用与结果：工具名get_weather；地点New York；返回Temperature: 72°F，Conditions: Partly cloudy。
